<?php require 'includes/db.php';require 'includes/helpers.php';require_login();ensure_default_categories($pdo);$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['name']??'');$icon=trim($_POST['icon']??'•')?:'•';if($name){try{$pdo->prepare("INSERT INTO categories(user_id,name,icon) VALUES(?,?,?)")->execute([user_id(),$name,$icon]);$msg='Category added.';}catch(Exception $e){$msg='That category already exists.';}}}$cats=$pdo->query("SELECT c.*,COUNT(t.id) used FROM categories c LEFT JOIN transactions t ON t.category_id=c.id GROUP BY c.id ORDER BY c.name")->fetchAll(PDO::FETCH_ASSOC);?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Categories</title><link rel="stylesheet" href="assets/style.css"></head><body class="<?=!empty($_SESSION['dark'])?'dark':''?>"><div class="app"><aside class="sidebar"><?php include 'includes/nav.php';?></aside><main class="main"><header class="top"><div><h1>Categories</h1><p>Organize your spending</p></div></header><div class="panel" style="max-width:650px"><?php if($msg):?><div class="alert"><?=$msg?></div><?php endif;?><form class="budget-form" method="post"><input name="icon" value="📌" style="max-width:90px"><input name="name" placeholder="Category name" required><button class="btn primary">Add</button></form></div><div class="cat-grid" style="margin-top:18px"><?php foreach($cats as $c):?><div class="cat"><span class="caticon"><?=h($c['icon'])?></span><div><b><?=h($c['name'])?></b><small><?=$c['used']?> transaction(s)</small></div></div><?php endforeach;?></div></main></div></body></html>